import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_over_depth(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups, bool has_bias);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Register-blocking factor along the output-width dimension. Each thread
// computes RTW consecutive output columns for a given (row, channel-tile),
// letting the per-(kh,kw,ci,co) weight value loaded from global memory be
// reused across RTW output pixels instead of being re-fetched per pixel.
#define RTW 8
#define RTH 2
__global__ void conv2d_over_depth_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin, int H, int W, int D,
    int Cout, int K, int stride, int pad, int dilation, int groups,
    int Hout, int Wout, int Dout,
    int Cin_g, int Cout_g,
    int in_tile_h, int in_tile_w,
    int cout_tile, int num_co_tiles)
{
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int OTW = blockDim.x * RTW;
    int OTH = blockDim.y * RTH;
    int wo_base = blockIdx.x * OTW + tx * RTW;
    int ho_base = blockIdx.y * OTH + ty * RTH;
    int zidx = blockIdx.z;
    int od = zidx % Dout;
    int tmp = zidx / Dout;
    int coTileIdx = tmp % num_co_tiles;
    int b = tmp / num_co_tiles;
    int co_base = coTileIdx * cout_tile;
    int g = co_base / Cout_g;
    int ci0 = g * Cin_g;
    int id = od * stride - pad; // kernel depth == 1, offset 0
    int wo[RTW];
    bool valid_w[RTW];
    bool any_valid_w = false;
    #pragma unroll
    for (int c = 0; c < RTW; ++c) {
        wo[c] = wo_base + c;
        valid_w[c] = (wo[c] < Wout);
        any_valid_w = any_valid_w || valid_w[c];
    }
    int ho[RTH];
    bool valid_h[RTH];
    bool any_valid_h = false;
    #pragma unroll
    for (int r = 0; r < RTH; ++r) {
        ho[r] = ho_base + r;
        valid_h[r] = (ho[r] < Hout);
        any_valid_h = any_valid_h || valid_h[r];
    }
    bool any_valid = any_valid_h && any_valid_w;
    int h0 = blockIdx.y * OTH * stride - pad;
    int w0 = blockIdx.x * OTW * stride - pad;
    extern __shared__ float smem[];
    int tile_elems0 = in_tile_h * in_tile_w;
    Tensor sX0 = make_tensor(make_smem_ptr(smem), make_shape(in_tile_h, in_tile_w), make_stride(in_tile_w, 1));
    Tensor sX1 = make_tensor(make_smem_ptr(smem + tile_elems0), make_shape(in_tile_h, in_tile_w), make_stride(in_tile_w, 1));
    Tensor gX = make_tensor(make_gmem_ptr(x), make_shape(B, Cin, D, H, W),
                        make_stride(Cin*D*H*W, D*H*W, H*W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w), make_shape(Cout, Cin_g, K, K, 1),
                        make_stride(Cin_g*K*K, K*K, K, 1, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y), make_shape(B, Cout, Hout, Wout, Dout),
                        make_stride(Cout*Hout*Wout*Dout, Hout*Wout*Dout, Wout*Dout, Dout, 1));
    // Double-buffered shared-memory staging of the per-(co,kh,kw) weight tile
    // for the current input channel, mirroring the input-tile pipelining above.
    // This turns weight reads from repeated global-memory fetches (one per
    // co_off/kh/kw per warp) into a single cooperative shared-memory load per
    // CTA per input channel, reused across the whole (kh,kw,co_off,RTW) loop.
    int weight_elems_total = cout_tile * K * K;
    Tensor sW0 = make_tensor(make_smem_ptr(smem + tile_elems0 * 2), make_shape(cout_tile, K, K), make_stride(K*K, K, 1));
    Tensor sW1 = make_tensor(make_smem_ptr(smem + tile_elems0 * 2 + weight_elems_total), make_shape(cout_tile, K, K), make_stride(K*K, K, 1));
    // Multiple output channels sharing the same (b, id) input tile are computed
    // cooperatively per CTA so the shared-memory staged input tile is reused
    // across 'cout_tile' output channels instead of being reloaded per-channel.
    // Additionally, each thread computes an RTH x RTW register-blocked tile of
    // output rows/columns so that the weight value loaded for a given
    // (co, ci, kh, kw) is reused across RTH*RTW pixels, further reducing
    // redundant global-memory weight traffic and shared-memory weight reads
    // compared to blocking along width alone.
    //
    // Software-pipelined (double-buffered) shared-memory staging: the input
    // tile for input-channel ci+1 is prefetched into the 'other' shared buffer
    // concurrently with the compute pass that consumes the tile for channel ci.
    // This overlaps global-memory load latency for the next tile with the
    // arithmetic work of the current tile instead of serializing every
    // channel's load and compute behind back-to-back __syncthreads() calls.
    const int MAX_COUT_TILE = 4;
    float acc[MAX_COUT_TILE][RTH][RTW];
    #pragma unroll
    for (int t = 0; t < MAX_COUT_TILE; ++t) {
        #pragma unroll
        for (int r = 0; r < RTH; ++r) {
            #pragma unroll
            for (int c = 0; c < RTW; ++c) acc[t][r][c] = 0.f;
        }
    }
    if (id >= 0 && id < D) {
        int tid = ty * blockDim.x + tx;
        int nthreads = blockDim.x * blockDim.y;
        int tile_elems = in_tile_h * in_tile_w;
        // Prime the pipeline: load the tile for the first input channel.
        {
            int c_ch = ci0 + 0;
            for (int idx = tid; idx < tile_elems; idx += nthreads) {
                int sh = idx / in_tile_w;
                int sw = idx % in_tile_w;
                int hh = h0 + sh;
                int ww = w0 + sw;
                float val = 0.f;
                if (hh >= 0 && hh < H && ww >= 0 && ww < W) {
                    val = gX(b, c_ch, id, hh, ww);
                }
                sX0(sh, sw) = val;
            }
        }
        // Cooperative shared-memory staging of the weight tile for the current
        // input channel (ci=0 priming step): avoids each thread independently
        // re-issuing the same global-memory weight load, instead loading it once
        // per CTA into shared memory for guaranteed cooperative reuse.
        {
            int weight_elems = cout_tile * K * K;
            for (int idx = tid; idx < weight_elems; idx += nthreads) {
                int co_off = idx / (K * K);
                int rem = idx % (K * K);
                int kh = rem / K;
                int kw = rem % K;
                int co = co_base + co_off;
                sW0(co_off, kh, kw) = gW(co, 0, kh, kw, 0);
            }
        }
        __syncthreads();
        for (int ci = 0; ci < Cin_g; ++ci) {
            bool cur_is_0 = (ci % 2 == 0);
            if (ci + 1 < Cin_g) {
                int c_ch_next = ci0 + ci + 1;
                for (int idx = tid; idx < tile_elems; idx += nthreads) {
                    int sh = idx / in_tile_w;
                    int sw = idx % in_tile_w;
                    int hh = h0 + sh;
                    int ww = w0 + sw;
                    float val = 0.f;
                    if (hh >= 0 && hh < H && ww >= 0 && ww < W) {
                        val = gX(b, c_ch_next, id, hh, ww);
                    }
                    if (cur_is_0) sX1(sh, sw) = val; else sX0(sh, sw) = val;
                }
            }
            if (ci + 1 < Cin_g) {
                int weight_elems = cout_tile * K * K;
                for (int idx = tid; idx < weight_elems; idx += nthreads) {
                    int co_off = idx / (K * K);
                    int rem = idx % (K * K);
                    int kh = rem / K;
                    int kw = rem % K;
                    int co = co_base + co_off;
                    float wv = gW(co, ci + 1, kh, kw, 0);
                    if (cur_is_0) sW1(co_off, kh, kw) = wv; else sW0(co_off, kh, kw) = wv;
                }
            }
            if (any_valid) {
                for (int co_off = 0; co_off < cout_tile; ++co_off) {
                    int co = co_base + co_off;
                    float local_acc[RTH][RTW];
                    #pragma unroll
                    for (int r = 0; r < RTH; ++r) {
                        #pragma unroll
                        for (int c = 0; c < RTW; ++c) local_acc[r][c] = 0.f;
                    }
                    for (int kh = 0; kh < K; ++kh) {
                        for (int kw = 0; kw < K; ++kw) {
                            float wv = cur_is_0 ? sW0(co_off, kh, kw) : sW1(co_off, kh, kw);
                            #pragma unroll
                            for (int r = 0; r < RTH; ++r) {
                                int sh = (ty * RTH + r) * stride + kh * dilation;
                                #pragma unroll
                                for (int c = 0; c < RTW; ++c) {
                                    int sw = (tx * RTW + c) * stride + kw * dilation;
                                    local_acc[r][c] += wv * (cur_is_0 ? sX0(sh, sw) : sX1(sh, sw));
                                }
                            }
                        }
                    }
                    #pragma unroll
                    for (int r = 0; r < RTH; ++r) {
                        #pragma unroll
                        for (int c = 0; c < RTW; ++c) acc[co_off][r][c] += local_acc[r][c];
                    }
                }
            }
            __syncthreads();
        }
    }
    if (any_valid) {
        for (int co_off = 0; co_off < cout_tile; ++co_off) {
            int co = co_base + co_off;
            float bval = (bias != nullptr) ? bias[co] : 0.f;
            #pragma unroll
            for (int r = 0; r < RTH; ++r) {
                if (!valid_h[r]) continue;
                #pragma unroll
                for (int c = 0; c < RTW; ++c) {
                    if (valid_w[c]) {
                        float out_val = acc[co_off][r][c] + bval;
                        gY(b, co, ho[r], wo[c], od) = out_val;
                    }
                }
            }
        }
    }
}
torch::Tensor conv2d_over_depth(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups, bool has_bias)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (B,C,H,W,D)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int B   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int H   = (int)x_c.size(2);
    int W   = (int)x_c.size(3);
    int D   = (int)x_c.size(4);
    // Permute input to depth-major contiguous layout (B,Cin,D,H,W) so that
    // the innermost dimension aligns with the width dimension being tiled,
    // turning the previously strided (stride=D) global loads used while
    // staging shared-memory input tiles into fully coalesced accesses.
    auto x_p = x_c.permute({0, 1, 4, 2, 3}).contiguous();
    int Cout = (int)w_c.size(0);
    int Cin_g = (int)w_c.size(1);
    int K = (int)w_c.size(2); // square kernel over H,W
    // w_c.size(3) == K, w_c.size(4) == 1
    int s = (int)stride;
    int p = (int)padding;
    int dil = (int)dilation;
    int gr = (int)groups;
    int Cout_g = Cout / gr;
    int Hout = (H + 2*p - dil*(K-1) - 1) / s + 1;
    int Wout = (W + 2*p - dil*(K-1) - 1) / s + 1;
    int Dout = (D + 2*p - dil*(1-1) - 1) / s + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid output size");
    const int TILE_X = 16;
    const int TILE_Y = 8;
    dim3 block(TILE_X, TILE_Y, 1);
    int OTW = TILE_X * RTW;
    int OTH = TILE_Y * RTH;
    // Choose how many output channels are processed per CTA so the shared-memory
    auto y = torch::empty({B, Cout, Hout, Wout, Dout}, x_c.options());
    // across multiple output channels instead of being reloaded once per channel.
    const int MAX_COUT_TILE = 4;
    int cout_tile = 1;
    for (int cand = MAX_COUT_TILE; cand >= 1; --cand) {
        if (Cout_g % cand == 0) { cout_tile = cand; break; }
    }
    int num_co_tiles = Cout / cout_tile;
    dim3 grid((Wout + OTW - 1) / OTW, (Hout + OTH - 1) / OTH,
               (unsigned)((long long)B * num_co_tiles * Dout));
    int in_tile_h = (OTH - 1) * s + (K - 1) * dil + 1;
    int in_tile_w = (OTW - 1) * s + (K - 1) * dil + 1;
    size_t smem_bytes = ((size_t)in_tile_h * (size_t)in_tile_w * 2 + (size_t)cout_tile * (size_t)K * (size_t)K * 2) * sizeof(float);
    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (has_bias) {
        bias_c = bias_opt.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv2d_over_depth_kernel<<<grid, block, smem_bytes, stream>>>(
        x_p.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
        B, Cin, H, W, D,
        Cout, K, s, p, dil, gr,
        Hout, Wout, Dout,
        Cin_g, Cout_g,
        in_tile_h, in_tile_w,
        cout_tile, num_co_tiles);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv2d_over_depth launch failed");
    // Output tensor is allocated directly in the final (B,Cout,Hout,Wout,Dout)
    // layout and the kernel writes into it using that layout's strides, so the
    // previously-required full-tensor permute+contiguous() copy pass over the
    // (very large) output buffer is eliminated entirely, removing a redundant
    // read+write of the whole output tensor from global memory.
    return y;
}
"""

_include_dir = "/workspace/cutegen_test/cutegen/cutlass/include"
cute_ext = load_inline(
    name="cute_conv3d_asym_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_over_depth"],
    extra_cflags=["-O3", f"-I{_include_dir}"],
    extra_cuda_cflags=["-O3", f"-I{_include_dir}"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution with kernel (kernel_size, kernel_size, 1)
    using a custom CUTE-based cooperative-tiled CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv3d purely as a parameter container (weight/bias init identical
        # to the reference implementation); its forward is not used.
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, 1),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=groups, bias=bias)
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous().float()
        weight = self.conv3d.weight
        if self.has_bias:
            bias = self.conv3d.bias
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        return self._ext.conv2d_over_depth(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups, self.has_bias
        )

